          title: 'Что такое тестирование и зачем оно нужно',
          content: 'Тестирование — это проверка того, что продукт работает так, как ожидают пользователь и бизнес. Тестировщик не «ломает программу ради спорта», а снижает риск того, что дефект дойдёт до клиента.\\n\\nВажно различать проверку (соответствие требованиям) и валидацию (решает ли продукт реальную задачу пользователя). Хороший QA держит в голове обе стороны.\\n\\nЧастая ошибка новичка — думать, что цель тестирования «доказать, что всё работает». На деле цель обратная: найти, где не работает. Мини-кейс: команда выпустила форму оплаты без проверки отрицательной суммы, пользователь ввёл «-100», система начислила деньги вместо списания — убыток. В портфолио это выглядит как: «Нашёл дефект логики оплаты при отрицательной сумме до релиза, предотвратил финансовые потери».',
          terms: ['Тестирование', 'Проверка', 'Валидация', 'Дефект'],
