          content: 'Цепочка «ошибка → дефект → отказ» — базовый словарь QA. Человек делает ошибку (mistake) в коде или требованиях, она превращается в дефект (defect/bug) в продукте, а при выполнении дефект вызывает отказ (failure), который видит пользователь.\\n\\nКачество — это степень, в которой продукт удовлетворяет заявленным и подразумеваемым потребностям. Оно не равно «отсутствию багов»: продукт без багов, но бесполезный для пользователя, некачественный.\\n\\nОшибка новичка — называть любой найденный баг «критическим». Мини-кейс: тестировщик завёл опечатку в подвале сайта как Blocker, разработчик потратил час вместо работы над падающей оплатой. В портфолио это выглядит как: «Классифицировал 40 дефектов по severity, что позволило команде чинить критичное в первую очередь».',
