          title: 'Углубление: эмуляторы и реальные устройства',
          content: 'Эмулятор — программная имитация мобильного устройства на компьютере. Он удобен и бесплатен, но не воспроизводит всё: реальную производительность, датчики, качество сети, поведение батареи.\\n\\nСтратегия зрелой команды — раннее тестирование на эмуляторах для скорости и обязательная финальная проверка критичных сценариев на реальных устройствах.\\n\\nОшибка новичка — полностью доверять эмулятору. Мини-кейс: жесты и производительность проверили только в эмуляторе, на реальном бюджетном телефоне прокрутка ленты тормозила и дёргалась, оценка в сторе упала до двух звёзд. В портфолио это выглядит как: «Выстроил стратегию проверки на эмуляторах и реальных устройствах, поймав деградацию прокрутки, невидимую в эмуляторе».',
          terms: ['Эмулятор', 'Реальное устройство', 'Производительность', 'Датчики'],
