      expectedResult: 'Вы пишете SELECT с условиями и JOIN для сверки данных между таблицами.',
      whyThisModule: 'Многие дефекты видны только в данных. Пропустив SQL, вы не сможете проверить, что заказ действительно сохранился и связался с пользователем, и будете верить интерфейсу на слово.',
