      title: 'Коммуникация и работа с командой',
      shortGoal: 'Доносить проблемы качества так, чтобы команда действовала, а не защищалась.',
      expectedResult: 'Вы формулируете обратную связь по фактам и конструктивно спорите о дефектах.',
      whyThisModule: 'QA постоянно сообщает плохие новости. Пропустив навык коммуникации, вы будете вызывать защитную реакцию, ваши баги будут игнорировать, а вас — считать «тем, кто мешает релизу».',
