          content: 'Не каждый найденный дефект команда согласится чинить. Иногда это осознанное решение с учётом сроков и рисков. QA приводит аргументы: частота, ущерб, число затронутых пользователей.\\n\\nСпорный дефект («это не баг, это фича») решается возвратом к требованиям, а не к громкости голоса. Кто прав — определяет спецификация, а не должность.\\n\\nОшибка новичка — либо молча соглашаться, либо спорить на эмоциях. Мини-кейс: тестировщик уступил в споре «это не баг» без ссылки на требование, дефект ушёл в прод и вызвал волну обращений в поддержку. В портфолио это выглядит как: «Отстаивал критичные дефекты ссылками на требования, а не эмоциями, добиваясь их исправления до релиза».',
