          content: 'Оценка — это прогноз, сколько времени займёт тестирование. Она нужна команде для планирования релиза. Оценивают по числу проверок, сложности фичи и рискам.\\n\\nЧестная оценка включает буфер на воспроизведение багов и повторные прогоны после исправлений. Голая оценка «на счастливый путь» всегда занижена.\\n\\nОшибка новичка — оценивать только время на первый прогон. Мини-кейс: тестировщик обещал закончить за день, забыл про регресс после исправлений, реально ушло три дня, релиз сдвинулся, доверие к оценкам упало. В портфолио это выглядит как: «Оценивал объём тестирования с буфером на повторные прогоны, повысив точность прогнозов сроков».',
