          title: 'Сессионное исследовательское тестирование',
          content: 'Исследовательское тестирование — это одновременное изучение продукта, придумывание тестов и их выполнение. Оно структурируется через хартию: короткую цель сессии на 60-90 минут.\\n\\nВо время сессии тестировщик ведёт заметки: что пробовал, что нашёл, какие вопросы возникли. Это превращает «тыканье» в воспроизводимую работу.\\n\\nОшибка новичка — считать, что исследование не требует дисциплины. Мини-кейс: тестировщик час свободно щёлкал, нашёл баг, но не записал шаги и не смог его повторить, дефект потеряли. В портфолио это выглядит как: «Проводил сессии исследовательского тестирования по хартиям с заметками, обеспечивая воспроизводимость найденных дефектов».',
