          id: 'm19-t02',
          title: 'Оформление кейса',
          content: 'Кейс в портфолио строится по схеме: ситуация → действие → результат. Ситуация даёт контекст, действие показывает ваш подход, результат — измеримую пользу.\\n\\nРезультат формулируют в терминах бизнеса: «предотвратил потерю данных», «сократил время регресса», а не «нашёл баг». Это язык, который понимает нанимающий менеджер.\\n\\nОшибка новичка — описывать процесс без результата. Мини-кейс: кандидат подробно описал, как тестировал форму, но не сказал, что нашёл и зачем это важно, интервьюер не понял ценности работы. В портфолио это выглядит как: «Оформлял кейсы по схеме ситуация-действие-результат с измеримой пользой для бизнеса».',
