/* ============================================================
   QA Study Portfolio — js/utils/course-data.js
   Заход 07.4.1 из 13: справки res-01 .. res-05
   Начало массива window.CourseData.resources
   Каждая справка: 5 разделов + копируемый артефакт
   ============================================================ */

window.CourseData.resources = [
  {
    id: 'res-01',
    title: 'Описание курса и как им пользоваться',
    estimatedTimeMinutes: 12,
    content: '## Проблема\nВы открыли учебный кабинет QA и не знаете, с чего начать. Модулей 23, вопросов сотни, легко утонуть и бросить на второй неделе.\n\n## Решение\n- Идите по модулям последовательно: каждый следующий опирается на предыдущий\n- На каждом уроке заполняйте поля: цель, своими словами, вывод — это превращает чтение в понимание\n- После модуля проходите контрольный тест, чтобы закрепить\n- Что не поняли — записывайте в поле «что непонятно», возвращайтесь через день\n- Раз в неделю проходите повторение по карточкам\n\n## Шаблон\nПлан на неделю:\n- День 1-2: изучить модуль (уроки + поля)\n- День 3: вопросы модуля\n- День 4: контрольный тест\n- День 5: повторение карточек\n- Выходные: оформить кейс в портфолио\n\n## Пример заполнения\nНеделя 1: модуль m01 Введение. Пн-Вт — прочитал два урока, заполнил цель и вывод. Ср — ответил на 12 вопросов. Чт — тест 8/10, переоткрыл слабые темы. Пт — повторил 6 карточек. Сб — оформил первый кейс.\n\n## Цена пропуска\nБез системы вы прочитаете модули по диагонали, не заполняя поля, и через месяц забудете 70% материала. Пустые поля урока = отсутствие понимания, а не экономия времени.'
  },
  {
    id: 'res-02',
    title: 'Структура модулей и уровней',
    estimatedTimeMinutes: 15,
    content: '## Проблема\nВы не понимаете, зачем модули разбиты на уровни и в каком порядке их проходить. Кажется, что можно перепрыгнуть к API, минуя основы.\n\n## Решение\nКурс разбит на 4 уровня, каждый открывается при 70% прогресса предыдущего. Уровни идут от базы к практике, чтобы вы не тестировали API, не понимая, что такое дефект.\n\nУровни курса:\n- Уровень 1 «База»: цель — освоить основы тестирования, требования и базовые техники тест-дизайна (модули m01-m06). Награда: значок «Фундамент заложен» и доступ к уровню «Ядро»\n- Уровень 2 «Ядро»: цель — научиться видам тестирования, веб-проверкам, планированию и работе с данными (модули m07, m10, m15-m17). Награда: значок «Практикующий тестировщик» и доступ к уровню «Профи»\n- Уровень 3 «Профи»: цель — освоить тестирование API, мобильных, SQL, баг-менеджмент и коммуникацию (модули m08-m09, m11-m14). Награда: значок «Технический QA» и доступ к уровню «Практика»\n- Уровень 4 «Практика»: цель — разобраться в автоматизации, собрать портфолио, подготовиться к собеседованию и пройти финальный проект (модули m18-m23). Награда: значок «Готов к найму» и открытый доступ к финальному проекту\n\n## Шаблон\nОтслеживание уровня:\n- Уровень: ___\n- Прогресс до разблокировки следующего: ___%\n- Осталось модулей до 70%: ___\n- Ближайшая награда: ___\n\n## Пример заполнения\nУровень: 1 «База». Прогресс: 55%. Осталось модулей до 70%: 2 (m05, m06). Ближайшая награда: значок «Фундамент заложен» и доступ к «Ядру». План: закрыть m05 и m06 за неделю.\n\n## Цена пропуска\nПерепрыгнув к API без основ, вы не поймёте, что проверять в ответе кроме статуса, и завалите первый же вопрос собеседования про тест-дизайн. Уровни существуют, чтобы фундамент был прочным до перехода к сложному.'
  },
  {
    id: 'res-03',
    title: 'Как выполнять практические задания',
    estimatedTimeMinutes: 14,
    content: '## Проблема\nПрактические задания кажутся сложными, и хочется подсмотреть ответ сразу. Но подсмотренный ответ не оставляет навыка — на собеседовании вы не сможете его воспроизвести.\n\n## Решение\n- Сначала попробуйте сами, засеките время из estimatedTimeMinutes\n- Застряли — откройте подсказку level_1 (наводящий вопрос), не ответ\n- Всё ещё сложно — level_2 (ссылка на нужный модуль), перечитайте\n- Только потом level_3 (частичный ответ)\n- Сверьтесь с эталоном и запишите, что упустили\n\n## Шаблон\nЖурнал практики:\n- Задание: ___\n- Моё решение: ___\n- Эталон: ___\n- Что упустил: ___\n- Вывод на будущее: ___\n\n## Пример заполнения\nЗадание: классы эквивалентности для email. Моё решение: валидный, без @, пустой. Эталон: + со спецсимволами. Что упустил: спецсимволы. Вывод: для строк всегда добавлять класс спецсимволов.\n\n## Цена пропуска\nПодсматривая ответ сразу, вы получаете иллюзию понимания. На собеседовании вопрос «разбей поле на классы» застанет врасплох, потому что вы никогда не делали это сами — только читали готовое.'
  },
  {
    id: 'res-04',
    title: 'Как вести конспект',
    estimatedTimeMinutes: 12,
    content: '## Проблема\nВы читаете модуль и через день не помните ничего. Пассивное чтение не работает — мозг не удерживает то, что не переработал.\n\n## Решение\n- Пишите не то, что прочитали, а что поняли — своими словами\n- Для каждого термина: определение + свой пример из жизни\n- Формулируйте одну ключевую мысль на урок\n- Записывайте, что осталось непонятным, и возвращайтесь\n- В конце — вывод: как применю это на работе\n\n## Шаблон\nКонспект урока:\n- Тема: ___\n- Своими словами: ___\n- Ключевая мысль: ___\n- Мой пример: ___\n- Что непонятно: ___\n- Вывод для работы: ___\n\n## Пример заполнения\nТема: граничные значения. Своими словами: проверяю края диапазона, там живут баги. Ключевая мысль: программисты путают > и >=. Мой пример: скидка от 1000 не сработала на 1000. Что непонятно: как границы у дат. Вывод: всегда проверять на, до и после границы.\n\n## Цена пропуска\nБез конспекта своими словами вы через неделю перечитываете модуль заново, тратя время дважды. Переписанный дословно текст бесполезен — понимание рождается только при переформулировании.'
  },
  {
    id: 'res-05',
    title: 'Как собирать портфолио',
    estimatedTimeMinutes: 16,
    content: '## Проблема\nУ вас есть знания, но нет доказательств. Работодатель не поверит на слово — ему нужны артефакты, показывающие, как вы мыслите.\n\n## Решение\n- Складывайте реальные артефакты: баг-репорты, чек-листы, Postman-коллекции, SQL-запросы\n- Каждый кейс оформляйте по схеме ситуация-действие-результат\n- Результат формулируйте на языке бизнеса: не «нашёл баг», а «предотвратил потерю заказов»\n- Минимум 3 кейса разных типов для готовности\n- Разнообразьте: баг-репорт, API-проверка, работа с базой\n\n## Шаблон\nКейс портфолио:\n- Ситуация: (контекст задачи) ___\n- Действие: (что и как сделал) ___\n- Результат: (измеримая польза бизнесу) ___\n- Артефакт: (ссылка на баг/чек-лист/коллекцию) ___\n- Техника: (какую применил) ___\n\n## Пример заполнения\nСитуация: форма оплаты падала на границе 1000 рублей. Действие: применил анализ границ, проверил 999/1000/1001, завёл баг с шагами. Результат: предотвратил потерю скидок на промо-акции до релиза. Артефакт: баг-репорт [Оплата] Скидка не срабатывает на пороге 1000. Техника: граничные значения.\n\n## Цена пропуска\nБез портфолио вы конкурируете с кандидатами, у которых есть примеры работ, имея только слова. Список пройденных курсов не заменит трёх кейсов — на собеседовании просят показать, а не рассказать.'
  }
];

